<?php $editing = isset($tagihan); $get = static fn(string $key, mixed $fallback = '') => old($key, $tagihan[$key] ?? $fallback); ?>
<section class="mb-6"><a href="<?= e(url('/tagihan')) ?>" class="text-sm font-semibold text-primary hover:underline">← Kembali ke tagihan</a><h1 class="mt-3 text-2xl font-bold text-slate-900"><?= e($title ?? 'Tambah Tagihan') ?></h1><p class="mt-1 text-sm text-slate-500">Masukkan tagihan untuk satu periode pelanggan.</p></section><form method="post" action="<?= e($action ?? url('/tagihan')) ?>" class="rounded-2xl bg-white p-5 shadow-card sm:p-7"><?= csrf_field() ?><?php if ($editing): ?><input type="hidden" name="_method" value="PUT"><?php endif; ?><div class="grid gap-5 md:grid-cols-2"><div><label class="form-label" for="npa">Pelanggan / NPA <span class="text-danger">*</span></label><select id="npa" name="npa" class="form-input" required <?= $editing ? 'disabled' : '' ?>><option value="">Pilih pelanggan</option><?php foreach ($pelanggan as $item): ?><option value="<?= e($item['npa']) ?>" <?= $get('npa') === $item['npa'] ? 'selected' : '' ?>><?= e($item['npa'] . ' — ' . $item['nama_pelanggan']) ?></option><?php endforeach; ?></select><?php if ($editing): ?><input type="hidden" name="npa" value="<?= e($get('npa')) ?>"><?php endif; ?><p class="form-error"><?= e(error('npa') ?? '') ?></p></div><div><label class="form-label" for="periode">Periode <span class="text-danger">*</span></label><input id="periode" type="date" name="periode" value="<?= e($get('periode', date('Y-m-01'))) ?>" class="form-input" required><p class="form-error"><?= e(error('periode') ?? '') ?></p></div><div><label class="form-label" for="meter_awal">Meter Awal</label><input id="meter_awal" type="number" min="0" name="meter_awal" value="<?= e($get('meter_awal')) ?>" class="form-input"></div><div><label class="form-label" for="meter_akhir">Meter Akhir</label><input id="meter_akhir" type="number" min="0" name="meter_akhir" value="<?= e($get('meter_akhir')) ?>" class="form-input"></div><div><label class="form-label" for="total_tagihan">Total Tagihan <span class="text-danger">*</span></label><input id="total_tagihan" type="number" min="0" step="0.01" name="total_tagihan" value="<?= e($get('total_tagihan')) ?>" class="form-input" required placeholder="0"><p class="form-error"><?= e(error('total_tagihan') ?? '') ?></p></div><div><label class="form-label" for="status_bayar">Status Bayar <span class="text-danger">*</span></label><select id="status_bayar" name="status_bayar" class="form-input"><option value="Belum Lunas" <?= $get('status_bayar','Belum Lunas') === 'Belum Lunas' ? 'selected' : '' ?>>Belum Lunas</option><option value="Lunas" <?= $get('status_bayar') === 'Lunas' ? 'selected' : '' ?>>Lunas</option></select></div><div id="tgl-bayar-wrap"><label class="form-label" for="tgl_bayar">Tanggal Bayar</label><input id="tgl_bayar" type="date" name="tgl_bayar" value="<?= e($get('tgl_bayar')) ?>" class="form-input"></div></div><div class="mt-7 flex justify-end gap-3 border-t border-slate-100 pt-5"><a href="<?= e(url('/tagihan')) ?>" class="rounded-xl border border-slate-200 px-5 py-3 text-sm font-semibold text-slate-600">Batal</a><button class="rounded-xl bg-primary px-5 py-3 text-sm font-semibold text-white">Simpan Tagihan</button></div></form>
